using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Security.Cryptography;using System.Web.Script.Serialization;using System.Diagnostics;using System.Threading;
namespace LaunchDesk.Development.RemoteProjectLab.Host
{
class LabVix {
 const string Dll="vix.dll";
 static LaunchDesk.Development.RemoteProjectLab.LabSettings settings;
 static string Vm { get { return settings.VmPath; } }
 static readonly List<object> Records=new List<object>();
 static string AttemptId;
 static int Result(object data,int code){var record=new{AttemptId=AttemptId,Utc=DateTime.UtcNow.ToString("o"),Stage=Stage,Data=data};Records.Add(record);if(settings!=null && AttemptId!=null){try{File.AppendAllText(Path.Combine(settings.EvidenceDirectory,"records.jsonl"),Json.Serialize(record)+Environment.NewLine);}catch{Console.WriteLine(Json.Serialize(new{ok=false,stage="evidence",error="Outcome record could not be saved; do not retry automatically."}));return 1;}}Console.WriteLine(Json.Serialize(data));return code;}
 static JavaScriptSerializer Json=new JavaScriptSerializer();static string Stage="initialization";
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool SetDllDirectory(string path);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixHost_Connect(int version,int type,IntPtr name,int port,IntPtr user,IntPtr pass,int options,int props,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern void VixHost_Disconnect(int host);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixHost_OpenVM(int host,IntPtr path,int options,int props,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern ulong VixPropertyList_AllocPropertyList(int host,out int list,int property,IntPtr value,int end);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern ulong VixJob_CheckCompletion(int job,IntPtr complete);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern ulong VixJob_GetError(int job);
 [DllImport(Dll,EntryPoint="Vix_GetProperties",CallingConvention=CallingConvention.Cdecl)]static extern ulong PropInt(int handle,int property,out int value,int end);
 [DllImport(Dll,EntryPoint="Vix_GetProperties",CallingConvention=CallingConvention.Cdecl)]static extern ulong PropPtr(int handle,int property,out IntPtr value,int end);
 [DllImport(Dll,EntryPoint="Vix_GetProperties",CallingConvention=CallingConvention.Cdecl)]static extern ulong PropBuffer(int handle,int property,IntPtr value,int end);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern void Vix_ReleaseHandle(int handle);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern void Vix_FreeBuffer(IntPtr value);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_LoginInGuest(int vm,IntPtr user,IntPtr pass,int options,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_LogoutFromGuest(int vm,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_CopyFileFromHostToGuest(int vm,IntPtr src,IntPtr dst,int opts,int props,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_CopyFileFromGuestToHost(int vm,IntPtr src,IntPtr dst,int opts,int props,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_RunProgramInGuest(int vm,IntPtr exe,IntPtr args,int opts,int props,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_PowerOff(int vm,int opts,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_CreateSnapshot(int vm,IntPtr name,IntPtr description,int opts,int props,IntPtr cb,IntPtr data);
 [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_ReadVariable(int vm,int type,IntPtr name,int opts,IntPtr cb,IntPtr data); [DllImport(Dll,CallingConvention=CallingConvention.Cdecl)]static extern int VixVM_PowerOn(int vm,int opts,int props,IntPtr cb,IntPtr data); class Buffer:IDisposable {public IntPtr P;int size;public Buffer(byte[] value){size=value.Length+1;P=Marshal.AllocHGlobal(size);Marshal.Copy(value,0,P,value.Length);Marshal.WriteByte(P,value.Length,0);}public Buffer(string value):this(Encoding.UTF8.GetBytes(value)){}public void Dispose(){if(P!=IntPtr.Zero){for(int i=0;i<size;i++)Marshal.WriteByte(P,i,0);Marshal.FreeHGlobal(P);P=IntPtr.Zero;}}}
 static void Check(ulong error){if(error!=0)throw new Exception("VIX error "+error+" (code "+(error&65535)+")");}
 static int Wait(int job){IntPtr flag=Marshal.AllocHGlobal(4);try{Stopwatch timer=Stopwatch.StartNew();while(true){Marshal.WriteInt32(flag,0);Check(VixJob_CheckCompletion(job,flag));if(Marshal.ReadByte(flag)!=0){Check(VixJob_GetError(job));return job;}if(timer.Elapsed.TotalSeconds>settings.TimeoutSeconds)throw new TimeoutException("VIX outcome unknown after deadline; do not retry side effects");Thread.Sleep(100);}}finally{Marshal.FreeHGlobal(flag);}}
 static int Handle(int job){int value;Check(PropInt(job,3010,out value,0));return value;}
 static int Integer(int handle,int id){int value;Check(PropInt(handle,id,out value,0));return value;}
 static string Text(int handle,int id){IntPtr value;Check(PropPtr(handle,id,out value,0));try{if(value==IntPtr.Zero)return "";int len=0;while(Marshal.ReadByte(value,len)!=0)len++;byte[] bytes=new byte[len];Marshal.Copy(value,bytes,0,len);return Encoding.UTF8.GetString(bytes);}finally{if(value!=IntPtr.Zero)Vix_FreeBuffer(value);}}
 static Buffer Secret(string name,out string user){var d=Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(name=="vm-access"?settings.VmCredentialFile:settings.GuestCredentialFile));if((string)d["Target"]!=settings.CredentialTarget)throw new Exception("Wrong credential target");user=(string)d["UserName"];byte[] bytes=ProtectedData.Unprotect(Convert.FromBase64String((string)d["ProtectedPassword"]),null,DataProtectionScope.CurrentUser);try{return new Buffer(bytes);}finally{Array.Clear(bytes,0,bytes.Length);}}
 static int Main(string[] args){int host=0,vm=0,props=0,connect=0,open=0;bool logged=false;List<int> jobs=new List<int>();try{LaunchDesk.Development.RemoteProjectLab.DevelopmentSwitch.RequireEnabled();LaunchDesk.Development.RemoteProjectLab.AddinGate.RequireLab();Stage="model";if(args.Length<5 || args[0]!="--model" || args[2]!="--confirm-target")throw new ArgumentException("Required: --model <path> --confirm-target <fingerprint> <action>");settings=LaunchDesk.Development.RemoteProjectLab.LabSettings.Read(args[1]);AttemptId=settings.SaveSnapshot(args[4]);Stage="target-validation";settings.VerifyTarget(args[3]);var rest=new string[args.Length-4];Array.Copy(args,4,rest,0,rest.Length);args=rest;
  if(args.Length==0)throw new Exception("Mode required"); if(args[0]=="set-guest"){var input=Json.Deserialize<Dictionary<string,string>>(Console.In.ReadToEnd());byte[] secret=Encoding.UTF8.GetBytes(input["password"]);try{File.WriteAllText(settings.GuestCredentialFile,Json.Serialize(new{UserName=input["username"],ProtectedPassword=Convert.ToBase64String(ProtectedData.Protect(secret,null,DataProtectionScope.CurrentUser)),Target=settings.CredentialTarget,CreatedUtc=DateTime.UtcNow.ToString("o")}));}finally{Array.Clear(secret,0,secret.Length);input.Clear();}Console.WriteLine("{\"ok\":true,\"stage\":\"guest-secret-updated\"}");return 0;}if(!File.Exists(settings.VixLibraryPath))throw new FileNotFoundException("Configured VIX library missing.");SetDllDirectory(Path.GetDirectoryName(settings.VixLibraryPath));Stage="host-connect";connect=Wait(VixHost_Connect(-1,3,IntPtr.Zero,0,IntPtr.Zero,IntPtr.Zero,0,0,IntPtr.Zero,IntPtr.Zero));host=Handle(connect);if(args[0]=="host"){return Result(new{ok=true,stage="host-connect",target=settings.CredentialTarget},0);}
  string ignored;using(Buffer pass=Secret("vm-access",out ignored))using(Buffer path=new Buffer(Vm)){Stage="open-exact-clone";Check(VixPropertyList_AllocPropertyList(host,out props,7001,pass.P,0));open=Wait(VixHost_OpenVM(host,path.P,0,props,IntPtr.Zero,IntPtr.Zero));vm=Handle(open);}
  if(!String.Equals(Text(vm,103),Vm,StringComparison.OrdinalIgnoreCase))throw new Exception("VM target verification failed");
  if(args[0]=="probe"){return Result(new{ok=true,stage="vm-open",toolsState=Integer(vm,152),powerState=Integer(vm,129),passwordsOnCommandLine=false},0);}
  if(args[0]=="readvar"){using(Buffer variable=new Buffer(args[2])){Stage="read-nonsecret-guest-variable";int job=VixVM_ReadVariable(vm,Int32.Parse(args[1]),variable.P,0,IntPtr.Zero,IntPtr.Zero);jobs.Add(job);Wait(job);return Result(new{ok=true,stage=Stage,name=args[2],value=Text(job,3056)},0);}} if(args[0]=="snapshot"){using(Buffer name=new Buffer(args[1]))using(Buffer desc=new Buffer("LaunchDesk lab G0 G1 verified baseline")){Stage="snapshot";int job=VixVM_CreateSnapshot(vm,name.P,desc.P,0,0,IntPtr.Zero,IntPtr.Zero);jobs.Add(job);Wait(job);return Result(new{ok=true,stage=Stage,target=settings.CredentialTarget},0);}} if(args[0]=="start"){Stage="power-on-test-clone";if((Integer(vm,129)&8)==0){int job=VixVM_PowerOn(vm,0,0,IntPtr.Zero,IntPtr.Zero);jobs.Add(job);Wait(job);}return Result(new{ok=true,stage=Stage,target=settings.CredentialTarget},0);} Stage="guest-login";string user;using(Buffer pass=Secret("guest-access",out user))using(Buffer name=new Buffer(user)){int login=VixVM_LoginInGuest(vm,name.P,pass.P,(args[0]=="login-interactive"?8:0),IntPtr.Zero,IntPtr.Zero);jobs.Add(login);Wait(login);logged=true;}
  int operation=0;
  if(args[0]=="login"||args[0]=="login-interactive"){return Result(new{ok=true,stage="guest-login",target=settings.CredentialTarget},0);}
  if(args[0]=="put"||args[0]=="get"){if(args.Length!=3)throw new Exception("Paths required");using(Buffer src=new Buffer(args[1]))using(Buffer dst=new Buffer(args[2])){Stage=args[0];operation=args[0]=="put"?VixVM_CopyFileFromHostToGuest(vm,src.P,dst.P,0,0,IntPtr.Zero,IntPtr.Zero):VixVM_CopyFileFromGuestToHost(vm,src.P,dst.P,0,0,IntPtr.Zero,IntPtr.Zero);jobs.Add(operation);Wait(operation);}}
  else if(args[0]=="run"){if(args.Length!=3)throw new Exception("Program and arguments required");using(Buffer exe=new Buffer(args[1]))using(Buffer command=new Buffer(args[2])){Stage="guest-program";operation=VixVM_RunProgramInGuest(vm,exe.P,command.P,0,0,IntPtr.Zero,IntPtr.Zero);jobs.Add(operation);Wait(operation);IntPtr code=Marshal.AllocHGlobal(8);try{Marshal.WriteInt64(code,0);Check(PropBuffer(operation,3018,code,0));long exit=Marshal.ReadInt64(code);return Result(new{ok=exit==0,stage=Stage,guestExitCode=exit},exit==0?0:2);}finally{Marshal.FreeHGlobal(code);}}}
  else if(args[0]=="stop"){Stage="guest-soft-stop";operation=VixVM_PowerOff(vm,4,IntPtr.Zero,IntPtr.Zero);jobs.Add(operation);Wait(operation);}
  else if(args[0]=="snapshot"){using(Buffer name=new Buffer(args[1]))using(Buffer desc=new Buffer("LaunchDesk G0/G1 lab checkpoint")){Stage="snapshot";operation=VixVM_CreateSnapshot(vm,name.P,desc.P,0,0,IntPtr.Zero,IntPtr.Zero);jobs.Add(operation);Wait(operation);}}
  else throw new Exception("Unsupported mode");
  return Result(new{ok=true,stage=Stage,target=settings.CredentialTarget},0);
 }catch(Exception e){return Result(new{ok=false,stage=Stage,error=e.Message},1);}
 finally {if(logged&&vm!=0){try{int job=VixVM_LogoutFromGuest(vm,IntPtr.Zero,IntPtr.Zero);Wait(job);Vix_ReleaseHandle(job);}catch{}}foreach(int job in jobs)if(job!=0)Vix_ReleaseHandle(job);if(vm!=0)Vix_ReleaseHandle(vm);if(open!=0)Vix_ReleaseHandle(open);if(props!=0)Vix_ReleaseHandle(props);if(host!=0)VixHost_Disconnect(host);if(connect!=0)Vix_ReleaseHandle(connect);}}
}
}
